def report():
    summary();guard();comp=load(OUT/'comparison.json');replay=load(OUT/'contextual-replay.json');lane=load(OUT/'lane-metrics.json');policy=load(OUT/'position-policy.json');val=load(OUT/'validation.json')
    temporal=load(OUT/'temporal-calibration-corrected.json');audit=load(OUT/'position-audit.json');taken=load(OUT/'taken-position-audit.json');gold=load(OUT/'golden-reference.json');probes=load(OUT/'behavior-probes.json');best=comp['best'];sections=[]
    def add(title,text):sections.append(f'## {len(sections)+1}. {title}\n\n{text}')
    def weighted(f,lens,field,sets=COMPATIBLE,pick=None):
        values=[lane['metrics'].get(s+'/'+f+'/'+lens+'/'+('pick='+str(pick) if pick else 'overall')) for s in sets];values=[v for v in values if v and v['n']]
        total=sum(v['n'] for v in values);return sum(v[field]*v['n'] for v in values)/total if total else None
